package cc.hyoban.moments.ui.design

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

// The app's own icons, as the design system draws them (its Icons group): a 24 grid, lines
// 1.75 wide with round ends and joins, a few filled marks. Drawn in black and tinted where
// they are shown, so each takes the colour of the text around it. Generated by
// scripts/icons/kotlin.py from scripts/icons/icons.py, the design system's source too.

/** One icon: [strokes] drawn as lines, [fills] filled; [mirror] for those that point a way, turned round right to left. */
private fun icon(name: String, mirror: Boolean, strokes: List<String>, fills: List<String> = emptyList()): ImageVector {
    val builder = ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f, autoMirror = mirror)
    strokes.forEach {
        builder.addPath(addPathNodes(it), stroke = SolidColor(Color.Black), strokeLineWidth = 1.75f, strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round)
    }
    fills.forEach { builder.addPath(addPathNodes(it), fill = SolidColor(Color.Black)) }
    return builder.build()
}

